        uint8 _step = 0;
        bool _result;
        while (true) {
            if (_step == 0) {
                if (_to == address(0)) revert();
                _step = 1;
            } else if (_step == 1) {
                if (!(_value > 0 && _value <= balances[_from])) revert();
                _step = 2;
            } else if (_step == 2) {
                if (!(_value <= allowed[_from][msg.sender])) revert();
                _step = 3;
            } else if (_step == 3) {
                allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
                _step = 4;
            } else if (_step == 4) {
                balances[_from] = balances[_from].sub(_value);
                _step = 5;
