pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract Vulnerable {
    // Vulnerable function: calls external contract with unchecked call
    function callRejecter(address target) external returns (bool) {
        // low-level call to target, ignoring success
        (bool success, ) = target.call(abi.encodeWithSignature("doSomething()"));
        // no require or check on success
        return true; // always returns true regardless of call success
    }
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecter fallback revert");
    }
    receive() external payable {
        revert("Rejecter receive revert");
    }
    function doSomething() external pure {
        revert("Rejecter doSomething revert");
    }
}

contract ExploitTest is Test {
    Vulnerable public vulnerable;
    Rejecter public rejecter;

    function setUp() public {
        vulnerable = new Vulnerable();
        rejecter = new Rejecter();
    }

    function test_exploit_unchecked_low_level_calls() public {
        // Call vulnerable.callRejecter with rejecter address
        // The low-level call inside will revert, but vulnerable ignores it and returns true
        bool txSucceeded = false;
        // We wrap call in try/catch to be sure outer call does NOT revert
        try vulnerable.callRejecter(address(rejecter)) returns (bool result) {
            txSucceeded = true;
            // result should be true regardless of inner call failure
            assertTrue(result, "Expected callRejecter to return true");
        } catch {
            // if this happens, exploit failed
            txSucceeded = false;
        }
        assertTrue(txSucceeded, "Outer transaction should succeed despite inner revert");

        // Confirm that calling the Rejecter directly reverts
        vm.expectRevert("Rejecter doSomething revert");
        rejecter.doSomething();

        // Confirm that calling fallback reverts
        (bool success, ) = address(rejecter).call("");
        assertTrue(!success, "Rejecter fallback call should fail");
    }
}

