contract TimedCrowdsaleTest is Test {
    TimedCrowdsale sale;

    function setUp() public {
        sale = new TimedCrowdsale();
    }

    function test_exploit_time_manipulation() public {
        // Warp to a timestamp before 1546300800 (Jan 1, 2019 00:00:00 UTC)
        vm.warp(1546290000);
        bool before = sale.isSaleFinished();
        // Warp to a timestamp equal or after 1546300800
        vm.warp(1546300800);
        bool after_ = sale.isSaleFinished();

        // Assert that before the timestamp the sale is not finished
        assertTrue(!before, "Sale should NOT be finished before timestamp");

        // Assert that after the timestamp the sale is finished
        assertTrue(after_, "Sale should be finished after timestamp");

        // Extra check: the timestamp at which sale finishes is exactly 1546300800
        vm.warp(1546300799);
        bool justBefore = sale.isSaleFinished();
        vm.warp(1546300800);
        bool justAfter = sale.isSaleFinished();
        assertTrue(!justBefore, "Sale not finished just before timestamp");
        assertTrue(justAfter, "Sale finished just after timestamp");
    }
}
